      anytrue([for m in one(data.aws_iam_principal_policy_simulation.pre_arm["${k}/${d}"].results).matched_statements : m.source_policy_id == local.deny_policy_name]), false)])
  }
  inert_trust = {
    Version = "2012-10-17"
    Statement = [
      { Sid = "NeverMatches", Effect = "Allow", Principal = { AWS = "arn:aws:iam::${var.aws_account_id}:root" }, Action = "sts:AssumeRole", Condition = { Null = { "aws:PrincipalArn" = "true" } } },
      { Sid = "UnassumableUntilCutoverDenyProven", Effect = "Deny", Principal = { AWS = "arn:aws:iam::${var.aws_account_id}:root" }, Action = "sts:AssumeRole" },
