        keys(each.value.assume_role_policy.Statement[0].Condition) == tolist(["StringEquals"]) &&
        each.value.assume_role_policy.Statement[0].Condition.StringEquals["token.actions.githubusercontent.com:aud"] == "sts.amazonaws.com" &&
