    }
  }
}

resource "aws_iam_role_policy" "this" {
  for_each = local.role_specs
  name     = local.inline_name[each.key]
  role     = aws_iam_role.this[each.key].id
  policy   = jsonencode(each.value.inline_policy)
}

resource "aws_iam_role_policy_attachment" "cutover_command_deny" {
  for_each   = local.role_specs
  role       = aws_iam_role.this[each.key].id
  policy_arn = var.cutover_command_deny_policy_arn
  depends_on = [aws_iam_role_policy.this]
  lifecycle {
    prevent_destroy = true
    precondition {
      condition     = try(endswith(var.cutover_command_deny_policy_arn, ":policy/crpko-${var.environment}-cutover-command-deny"), false)
      error_message = "Every role needs this environment's cutover command Deny policy (ECS on EC2 3.3)."
    }
  }
}

data "aws_iam_principal_policy_simulation" "cutover_command_deny" {
  for_each = { for pair in setproduct(keys(local.role_specs), local.documents) : "${pair[0]}/${pair[1]}" => pair if var.simulation_enabled }
  policy_source_arn = aws_iam_role.this[each.value[0]].arn
  action_names      = ["ssm:SendCommand"]
  resource_arns     = ["arn:aws:ssm:${var.aws_region}:${var.aws_account_id}:document/crpko-${var.environment}-${each.value[1]}"]
  depends_on        = [aws_iam_role_policy_attachment.cutover_command_deny]
  lifecycle {
    postcondition {
      condition = try(length(self.results) == 1 && one(self.results).action_name == "ssm:SendCommand" &&
        one(self.results).resource_arn == one(self.resource_arns) && one(self.results).decision == "explicitDeny" &&
        length(one(self.results).missing_context_keys) == 0 &&
        anytrue([for m in one(self.results).matched_statements : m.source_policy_id == local.deny_policy_name]), false)
      error_message = "Cutover command Deny proof failed: require this policy's explicitDeny with no missing context on each document."
    }
  }
}
